import { Show, createRenderEffect, createUniqueId, onCleanup, onMount, splitProps, type JSX } from 'solid-js';
import { getTextareaAriaProps, getTextareaIds } from '../lib/core';
import type { TextareaBaseProps } from '../lib/core';
import { invokeEventHandler } from '../lib/utils';
import { createFormResetBinding, setInitialNativeValue } from '../lib/utils';
import styles from './textarea.module.scss';

export interface TextareaProps extends JSX.TextareaHTMLAttributes<HTMLTextAreaElement>, TextareaBaseProps {
	/** 非受控初始值；Solid JSX 未声明原生 defaultValue 属性。 */
	defaultValue?: string;
	/** 值变化回调；受控状态由原生 value 属性决定。 */
	onChangeValue?: (value: string) => void;
}

/** SolidJS Textarea：复用 core 的 ID/ARIA 推导，并与 Input 保持相同值契约。 */
export function Textarea(props: TextareaProps) {
	const [local, rest] = splitProps(props, [
		'label',
		'error',
		'helperText',
		'required',
		'id',
		'value',
		'defaultValue',
		'onChangeValue',
		'onInput',
		'class',
		'ref',
		'children',
		'aria-describedby',
		'aria-invalid',
	]);
	const fallbackId = `tile-solid-textarea-${createUniqueId()}`;
	const textareaId = () => local.id ?? fallbackId;
	const ids = () => getTextareaIds(textareaId());
	const aria = () => getTextareaAriaProps(ids(), local.error, local.helperText);
	const initialValue = String(local.value ?? local.defaultValue ?? local.children ?? '');
	let textarea: HTMLTextAreaElement | undefined;
	const resetBinding = createFormResetBinding(() => {
		queueMicrotask(() => {
			if (textarea && local.value !== undefined) textarea.value = String(local.value);
		});
	});
	const assignTextarea = (element: HTMLTextAreaElement) => {
		textarea = element;
		if (typeof local.ref === 'function') local.ref(element);
	};
	const describedBy = () => [...new Set([local['aria-describedby'], aria()['aria-describedby']].filter((value): value is string => Boolean(value)))].join(' ') || undefined;
	const invalid = () => (local.error ? true : local['aria-invalid']);

	createRenderEffect(() => {
		const controlledValue = local.value;
		if (textarea && controlledValue !== undefined) textarea.value = String(controlledValue);
	});

	onMount(() => {
		if (!textarea) return;
		setInitialNativeValue(textarea, initialValue);
		textarea.value = local.value === undefined ? initialValue : String(local.value);
		resetBinding.bind(textarea);
	});
	onCleanup(() => resetBinding.cleanup());

	return (
		<div class={styles.textareaWrapper}>
			<Show when={local.label}>
				<label for={textareaId()} class={`${styles.label} ${local.required ? styles.required : ''}`}>
					{local.label}
				</label>
			</Show>
			<textarea
				{...rest}
				ref={assignTextarea}
				id={textareaId()}
				class={`${styles.textarea} ${local.error ? styles.error : ''} ${local.class ?? ''}`}
				required={local.required}
				aria-invalid={invalid()}
				aria-describedby={describedBy()}
				onInput={(event) => {
					const next = event.currentTarget.value;
					invokeEventHandler(local.onInput, event);
					if (local.value !== undefined) event.currentTarget.value = String(local.value);
					if (!event.defaultPrevented) local.onChangeValue?.(next);
				}}>
				{initialValue}
			</textarea>
			<Show when={local.error}>
				<span id={ids().error} class={styles.errorText}>
					{local.error}
				</span>
			</Show>
			<Show when={!local.error && local.helperText}>
				<span id={ids().helper} class={styles.helperText}>
					{local.helperText}
				</span>
			</Show>
		</div>
	);
}

export default Textarea;

@use '../../../styles/variables/colors' as *;

.textareaWrapper {
	display: flex;
	flex-direction: column;
	gap: var(--tile-textarea-label-gap, #{$spacing-1});
	width: 100%;
}

.textarea {
	display: flex;
	min-height: var(--tile-textarea-min-height, 5rem);
	width: 100%;
	border-radius: var(--tile-textarea-radius, #{$radius});
	border: var(--tile-textarea-border-width, 1px) solid var(--tile-textarea-border, #{$border});
	background-color: var(--tile-textarea-background, #{$background});
	padding: var(--tile-textarea-padding, #{$spacing-3} #{$spacing-3});
	font-size: var(--tile-textarea-font-size, #{$text-sm});
	box-shadow: var(--tile-textarea-shadow, none);
	color: $foreground;
	transition: all $transition-fast;
	outline: none;
	resize: vertical;
	font-family: inherit;
	line-height: var(--tile-textarea-line-height, #{$leading-normal});

	&::placeholder {
		color: var(--tile-textarea-placeholder, #{$muted-foreground});
	}

	&:focus {
		outline: none;
		border-color: var(--tile-textarea-focus-border, #{$ring});
		box-shadow: var(--tile-textarea-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled,
	&.disabled {
		pointer-events: none;
		opacity: var(--tile-textarea-disabled-opacity, 0.5);
		cursor: not-allowed;
		background-color: var(--tile-textarea-disabled-background, #{$field-disabled});
		color: var(--tile-textarea-disabled-color, #{$foreground});
	}

	&.error {
		border-color: $destructive;
		box-shadow: var(--tile-textarea-error-shadow, none);

		&:focus {
			border-color: $destructive;
			box-shadow: var(--tile-textarea-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}
}

.label {
	display: block;
	font-size: var(--tile-textarea-label-font-size, #{$text-sm});
	font-weight: $font-medium;
	color: $foreground;
	line-height: $leading-normal;

	&.required::after {
		content: ' *';
		color: $destructive;
	}
}

.helperText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: var(--tile-textarea-description-color, #{$muted-foreground});
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}

.errorText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: $destructive;
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}
